function phase(text) {
  const status = game.find('Lab Status');
  if (status) status.text = text;
  game.log(text);
}

function begin(self) {
  game.spine.setSkin(self, 'relay-base', ['copper-shell', 'amber-antenna']);
  game.spine.play(self, 'charge', { mixDuration: 0.18 });
  game.spine.play(self, 'fin-flutter', { track: 1, loop: true, weight: 0.55 });
  phase('CHARGING');
}

export function start(self) {
  begin(self);
}

export function update(self) {
  const antenna = game.spine.bone(self, 'antenna');
  const marker = game.find('Antenna Tracker');
  if (!antenna || !marker) return;
  marker.x = antenna.x - 4.5;
  marker.y = antenna.y - 12;
}

export function onMessage(self, message) {
  if (message === 'relay-replay') begin(self);
}

export function onSpineEvent(self, signal) {
  if (signal.track === 0 && signal.name === 'charged') {
    game.spine.resetSkin(self);
    phase('CHIME / HOP');
  }
}

export function onSpineComplete(self, signal) {
  if (signal.track !== 0 || signal.animation !== 'hop') return;
  game.spine.play(self, 'idle', { loop: true, mixDuration: 0.2 });
  phase('IDLE / REPLAY');
}

